create table empleado (
	id int NOT NULL PRIMARY KEY AUTO_INCREMENT,
	nombre VARCHAR(50) NOT NULL,
	area VARCHAR(50) NOT NULL,
	email VARCHAR(50),
	pais VARCHAR(50),
	salario INT
);


-- CONSULTAS BASICAS
select * from empleado;

select nombre, area, pais, salario
from empleado;

-- FILTROS
select *
from empleado
where pais = 'Peru';

select *
from empleado
where salario > 5000;

select *
from empleado
where salario between 3000 and 7000;

select *
from empleado
where area = 'Engineering';

select *
from empleado
where nombre like '%a%';

select *
from empleado
where pais in ('Peru', 'Colombia', 'Mexico');

select *
from empleado
where email is not null;

-- ORDENAMIENTO
select *
from empleado
order by salario asc;

select *
from empleado
order by salario desc;

select *
from empleado
order by pais asc, salario desc;

-- LIMIT
select *
from empleado
limit 10;

select *
from empleado
order by salario desc
limit 5;

-- AGREGACIONES
select count(*) as total_empleados
from empleado;

select sum(salario) as suma_salarios
from empleado;

select avg(salario) as promedio_salario
from empleado;

select min(salario) as salario_minimo, max(salario) as salario_maximo
from empleado;

-- AGRUPACIONES
select pais, count(*) as total
from empleado
group by pais
order by total desc;

select area, count(*) as total
from empleado
group by area
order by total desc;

select pais, round(avg(salario), 2) as salario_promedio
from empleado
group by pais
order by salario_promedio desc;

select area, round(avg(salario), 2) as salario_promedio
from empleado
group by area
order by salario_promedio desc;

select pais, sum(salario) as planilla_total
from empleado
group by pais
order by planilla_total desc;

-- HAVING
select pais, count(*) as total
from empleado
group by pais
having count(*) >= 20
order by total desc;

select area, round(avg(salario), 2) as salario_promedio
from empleado
group by area
having avg(salario) > 5000
order by salario_promedio desc;
